<script setup>
import { ref, computed, onMounted } from 'vue'
import { commerceService, commerceError } from '../services/commerceService'
import { money } from '../utils/money'
import { useLiveRefresh } from '../composables/useLiveRefresh'
import ProductImage from '../components/ProductImage.vue'
const orders = ref([]), loading = ref(false), error = ref(''), page = ref(0), status = ref(''), emptyNext = ref(false)
const visible = computed(() => orders.value.filter(o => status.value === '' || o.status === Number(status.value)))
async function load() { if (loading.value) return; loading.value = true; try { const rows = await commerceService.orders(page.value); orders.value = rows; emptyNext.value = rows.length < 20; error.value = '' } catch (e) { error.value = commerceError(e) } finally { loading.value = false } }
function changePage(delta) { page.value += delta; load() }
onMounted(load); useLiveRefresh(load, 60000)
</script>
<template><div class="container shop-page"><header class="shop-heading"><span class="eyebrow">YOUR ORDERS</span><h1>Đơn hàng của bạn</h1><p>Theo dõi từng bước trên hành trình giao hàng.</p></header><label class="order-filter">Trạng thái<select v-model="status"><option value="">Tất cả trong trang</option><option value="0">Chờ xác nhận</option><option value="1">Đã xác nhận</option><option value="2">Chờ lấy hàng</option><option value="3">Đang giao hàng</option><option value="4">Đã giao hàng</option><option value="5">Hoàn thành</option><option value="6">Đã hủy</option><option value="7">Hoàn tiền</option><option value="9">Giao hàng thất bại</option></select></label><p v-if="error" class="shop-alert" role="alert">{{ error }} <button type="button" class="text-button" @click="load">Thử lại</button></p><p v-if="loading && !orders.length" class="shop-card" role="status">Đang tải đơn hàng…</p><section v-else-if="!orders.length && !error" class="shop-card shop-empty"><h2>{{ page === 0 ? 'Bạn chưa có đơn hàng.' : 'Không có thêm đơn hàng.' }}</h2><RouterLink class="button button-primary" to="/san-pham">Khám phá bộ sưu tập</RouterLink></section><p v-else-if="!visible.length" class="shop-card">Không có đơn ở trạng thái này trong trang.</p><article v-for="order in visible" :key="order.code" class="shop-card order-list-card"><header><RouterLink :to="'/don-hang/' + order.code"><strong>#{{ order.code }}</strong></RouterLink><span class="order-status" :class="{ canceled: order.status >= 6 }">{{ order.statusLabel }}</span></header><div class="order-list-preview"><ProductImage :src="order.items[0]?.image" :alt="order.items[0]?.name || 'Đơn hàng'" /><div><h2>{{ order.items[0]?.name || 'Đơn hàng' }}</h2><p class="shop-muted">{{ order.items.reduce((n, i) => n + i.quantity, 0) }} sản phẩm · {{ new Date(order.createdAt).toLocaleString('vi-VN') }}</p></div><strong>{{ money(order.total) }}</strong></div><footer><RouterLink :to="'/don-hang/' + order.code" class="button button-outline">Xem chi tiết →</RouterLink></footer></article><nav v-if="page > 0 || orders.length" class="pagination" aria-label="Trang đơn hàng"><button :disabled="page === 0 || loading" @click="changePage(-1)">← Trước</button><span>Trang {{ page + 1 }}</span><button :disabled="emptyNext || loading" @click="changePage(1)">Sau →</button></nav></div></template>
